import sys, platform, unicodedata, encodings.idna, json
inputs = [[], [65], [0], list(range(128)), [0xad], [0x200b], [0xff21], [0xdf], [0x1e9e], [0x212a], [0x33c6], [0xd800], [0xdc80], [0x5d0,49,0x5d1], [0x5d0,65], [97,0x5d0], [0x1f600]]
for n in (0,1,2,55,56,57,58,59,60,62,63,64,65,128):
    for prefix in ([], [120,110,45,45], [88,78,45,45]):
        for p in (65,0xe9,0xdf,0xad,0x1f600):
            inputs.append(prefix + [p]*n)
for prefix in ('xn--', 'XN--', 'xN--'):
    inputs.append(list(map(ord,prefix))+[0xe9])
rows=[]
for points in inputs:
    value=''.join(map(chr,points))
    try: row={'input':points,'result':list(encodings.idna.ToASCII(value))}
    except UnicodeEncodeError as e: row={'input':points,'error':{'name':type(e).__name__,'encoding':e.encoding,'object':list(map(ord,e.object)),'start':e.start,'end':e.end,'reason':e.reason,'message':str(e)}}
    rows.append(row)
print(json.dumps({'oracle':{'executable':sys.executable,'version':sys.version,'platform':platform.platform(),'unicode':unicodedata.unidata_version,'source':open(__file__).read()},'cases':rows},indent=2))
